890|         break;
891|
892|      case PNG_COLOR_TYPE_RGB:
893|         png_ptr->channels = 3;
894|         break;
895|
896|      case PNG_COLOR_TYPE_GRAY_ALPHA:
897|         png_ptr->channels = 2;
898|         break;
899|
900|      case PNG_COLOR_TYPE_RGB_ALPHA:
901|         png_ptr->channels = 4;
902|         break;
903|   }
