38|static size_t
39|safe_read(png_structp png_ptr, int fd, void *buffer_in, size_t nbytes)
40|{
41|   size_t ntotal = 0;
42|   char *buffer = png_voidcast(char*, buffer_in);
43|
44|   while (nbytes > 0)
45|   {
46|      unsigned int nread;
47|      int iread;
48|
49|      /* Passing nread > INT_MAX to read is implementation defined in POSIX
50|       * 1003.1, therefore despite the unsigned argument portable code must
51|       * limit the value to INT_MAX!
52|       */
53|      if (nbytes > INT_MAX)
54|         nread = INT_MAX;
55|
56|      else
57|         nread = (unsigned int)/*SAFE*/nbytes;
58|
59|      iread = read(fd, buffer, nread);
60|
61|      if (iread == -1)
62|      {
63|         /* This is the devil in the details, a read can terminate early with 0
64|          * bytes read because of EINTR, yet it still returns -1 otherwise end
65|          * of file cannot be distinguished.
66|          */
67|         if (errno != EINTR)
68|         {
69|            png_warning(png_ptr, "/proc read failed");
70|            return 0; /* I.e., a permanent failure */
71|         }
72|      }
73|
74|      else if (iread < 0)
75|      {
76|         /* Not a valid 'read' result: */
77|         png_warning(png_ptr, "OS /proc read bug");
78|         return 0;
79|      }
80|
81|      else if (iread > 0)
82|      {
83|         /* Continue reading until a permanent failure, or EOF */
84|         buffer += iread;
85|         nbytes -= (unsigned int)/*SAFE*/iread;
86|         ntotal += (unsigned int)/*SAFE*/iread;
87|      }
88|
89|      else
90|         return ntotal;
91|   }
92|
93|   return ntotal; /* nbytes == 0 */
94|}

96|static int
97|png_have_neon(png_structp png_ptr)
98|{
99|   int fd = open("/proc/self/auxv", O_RDONLY);
100|   Elf32_auxv_t aux;
101|
102|   /* Failsafe: failure to open means no NEON */
103|   if (fd == -1)
104|   {
105|      png_warning(png_ptr, "/proc/self/auxv open failed");
106|      return 0;
107|   }
108|
109|   while (safe_read(png_ptr, fd, &aux, sizeof aux) == sizeof aux)
110|   {
111|      if (aux.a_type == AT_HWCAP && (aux.a_un.a_val & HWCAP_NEON) != 0)
112|      {
113|         close(fd);
114|         return 1;
115|      }
116|   }
117|
118|   close(fd);
119|   return 0;
120|}

24|static int
25|png_have_neon(png_structp png_ptr)
26|{
27|   FILE *f = fopen("/proc/cpuinfo", "rb");
28|
29|   if (f != NULL)
30|   {
31|      /* This is a simple state machine which reads the input byte-by-byte until
32|       * it gets a match on the 'neon' feature or reaches the end of the stream.
33|       */
34|      static const char ch_feature[] = { 70, 69, 65, 84, 85, 82, 69, 83 };
35|      static const char ch_neon[] = { 78, 69, 79, 78 };
36|
37|      enum
38|      {
39|         StartLine, Feature, Colon, StartTag, Neon, HaveNeon, SkipTag, SkipLine
40|      }  state;
41|      int counter;
42|
43|      for (state=StartLine, counter=0;;)
44|      {
45|         int ch = fgetc(f);
46|
47|         if (ch == EOF)
48|         {
49|            /* EOF means error or end-of-file, return false; neon at EOF is
50|             * assumed to be a mistake.
51|             */
52|            fclose(f);
53|            return 0;
54|         }
55|
56|         switch (state)
57|         {
58|            case StartLine:
59|               /* Match spaces at the start of line */
60|               if (ch <= 32) /* skip control characters and space */
61|                  break;
62|
63|               counter=0;
64|               state = Feature;
65|               /* FALLTHROUGH */
66|
67|            case Feature:
68|               /* Match 'FEATURE', ASCII case insensitive. */
69|               if ((ch & ~0x20) == ch_feature[counter])
70|               {
71|                  if (++counter == (sizeof ch_feature))
72|                     state = Colon;
73|                  break;
74|               }
75|
76|               /* did not match 'feature' */
77|               state = SkipLine;
78|               /* FALLTHROUGH */
79|
80|            case SkipLine:
81|            skipLine:
82|               /* Skip everything until we see linefeed or carriage return */
83|               if (ch != 10 && ch != 13)
84|                  break;
85|
86|               state = StartLine;
87|               break;
88|
89|            case Colon:
90|               /* Match any number of space or tab followed by ':' */
91|               if (ch == 32 || ch == 9)
92|                  break;
93|
94|               if (ch == 58) /* i.e. ':' */
95|               {
96|                  state = StartTag;
97|                  break;
98|               }
99|
100|               /* Either a bad line format or a 'feature' prefix followed by
101|                * other characters.
102|                */
103|               state = SkipLine;
104|               goto skipLine;
105|
106|            case StartTag:
107|               /* Skip space characters before a tag */
108|               if (ch == 32 || ch == 9)
109|                  break;
110|
111|               state = Neon;
112|               counter = 0;
113|               /* FALLTHROUGH */
114|
115|            case Neon:
116|               /* Look for 'neon' tag */
117|               if ((ch & ~0x20) == ch_neon[counter])
118|               {
119|                  if (++counter == (sizeof ch_neon))
120|                     state = HaveNeon;
121|                  break;
122|               }
123|
124|               state = SkipTag;
125|               /* FALLTHROUGH */
126|
127|            case SkipTag:
128|               /* Skip non-space characters */
129|               if (ch == 10 || ch == 13)
130|                  state = StartLine;
131|
132|               else if (ch == 32 || ch == 9)
133|                  state = StartTag;
134|               break;
135|
136|            case HaveNeon:
137|               /* Have seen a 'neon' prefix, but there must be a space or new
138|                * line character to terminate it.
139|                */
140|               if (ch == 10 || ch == 13 || ch == 32 || ch == 9)
141|               {
142|                  fclose(f);
143|                  return 1;
144|               }
145|
146|               state = SkipTag;
147|               break;
148|
149|            default:
150|               png_error(png_ptr, "png_have_neon: internal error (bug)");
151|         }
152|      }
153|   }
154|
155|#ifdef PNG_WARNINGS_SUPPORTED
156|   else
157|      png_warning(png_ptr, "/proc/cpuinfo open failed");
158|#endif
159|
160|   return 0;
161|}
